"""Run on the owner's machine. Never print tokens or make chat messages."""
import argparse
import asyncio
import os
import re
from urllib.parse import urlsplit

import httpx
from aiogram import Bot
from config import load_config
from transport import telegram_session


class SetupError(RuntimeError):
    """Only fixed, non-secret messages generated by this setup command."""


def validate_url(url):
    parsed = urlsplit(url)
    if (parsed.scheme != 'https' or not parsed.hostname or parsed.username or parsed.password
            or parsed.query or parsed.fragment or parsed.path != '/api/telegram'):
        raise SetupError('Use the public HTTPS production URL ending in /api/telegram')
    return parsed


async def check_endpoint(url, secret):
    parsed = validate_url(url)
    if not re.fullmatch(r'[A-Za-z0-9_-]{32,256}', secret):
        raise SetupError('WEBHOOK_SECRET must contain 32-256 URL-safe characters')
    async with httpx.AsyncClient(timeout=20, follow_redirects=False) as client:
        health = await client.get(f'{parsed.scheme}://{parsed.netloc}/health')
        if health.status_code != 200 or health.json().get('mode') != 'webhook':
            raise SetupError('Webhook health route is not reachable')
        rejected = await client.post(url, json={})
        if rejected.status_code != 401:
            raise SetupError('Webhook is not publicly reachable or does not reject unauthenticated requests')
        # An invalid Update with the correct header must reach validation, but sends nothing.
        validated = await client.post(url, json={}, headers={'X-Telegram-Bot-Api-Secret-Token': secret})
        if validated.status_code != 400:
            raise SetupError('Local and deployed webhook secrets do not match, or the route is wrong')
    print('Public webhook health, authentication and secret binding OK; no chat message sent.')


async def run(args):
    cfg = load_config()
    secret = os.getenv('WEBHOOK_SECRET', '')
    if args.command == 'check':
        await check_endpoint(args.url, secret)
        return
    if args.command == 'set':
        await check_endpoint(args.url, secret)
    async with Bot(cfg.bot_token, session=telegram_session(cfg.proxy_url)) as bot:
        if args.command == 'set':
            await bot.set_webhook(args.url, secret_token=secret, allowed_updates=['message', 'callback_query'],
                                  max_connections=1, drop_pending_updates=False)
            print('Webhook registered. Local polling must remain stopped.')
        elif args.command == 'delete':
            await bot.delete_webhook(drop_pending_updates=False)
            print('Webhook removed; queued updates preserved. Polling may now start.')
        info = await bot.get_webhook_info()
        # Only public routing/status metadata, never credentials or raw provider errors.
        print('Webhook URL:', info.url or '(none)')
        print('Pending updates:', info.pending_update_count)
        print('Delivery error present:', bool(info.last_error_message))


if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    sub = parser.add_subparsers(dest='command', required=True)
    for action in ('check', 'set', 'status', 'delete'):
        command = sub.add_parser(action)
        if action in ('check', 'set'):
            command.add_argument('--url', required=True)
    args = parser.parse_args()
    try:
        asyncio.run(run(args))
    except SetupError as exc:
        print(str(exc))
        raise SystemExit(1) from None
    except Exception as exc:
        print(f'Webhook command failed ({type(exc).__name__}); check configuration, deployment and connectivity.')
        raise SystemExit(1) from None
